<template>
  <main class="analysis-page">
    <header class="page-heading"><div><small>CONTENT ANALYTICS</small><h1>数据分析</h1><p>用数据了解内容表现，用 AI 辅助下一轮内容决策。</p></div><div class="actions"><button @click="scrollToReport">查看报告</button><button class="primary" :disabled="loading" @click="fileInput?.click()">{{ loading?'分析中…':'↑ 上传数据' }}</button><input ref="fileInput" hidden type="file" accept=".xlsx,.csv,.txt" @change="handleFileUpload"></div></header>
    <section class="upload"><b>⇧</b><div><strong>{{analysisStore.fileInfo?.name||'导入运营数据'}}</strong><p>{{fileDesc}}</p></div><button :disabled="loading" @click="fileInput?.click()">选择文件</button></section>
    <div v-if="loading" class="notice">AI 正在读取数据并生成运营分析，请稍候…</div>
    <div v-if="errorMessage" class="notice error">{{errorMessage}} <button @click="errorMessage=''">×</button></div>
    <div v-if="showPreview" class="preview-mask" @click.self="cancelPreview">
      <section class="preview-dialog">
        <header class="preview-title"><div><small>DATA CHECK</small><h2>确认数据字段</h2><p>已读取 {{ sourceRows.length }} 行数据。请确认文件字段与系统字段的对应关系。</p></div><button class="close-button" @click="cancelPreview">×</button></header>
        <div class="mapping-grid"><label v-for="header in sourceHeaders" :key="header"><span>{{ header }}</span><select v-model="fieldMapping[header]"><option value="">忽略该字段</option><option v-for="field in standardFields" :key="field.key" :value="field.key">{{ field.label }}</option></select></label></div>
        <div v-if="mappingWarnings.length" class="mapping-warning"><b>需要确认</b><span v-for="warning in mappingWarnings" :key="warning">{{ warning }}</span></div>
        <div v-if="errorMessage" class="notice error preview-error">{{ errorMessage }}<button @click="errorMessage=''">×</button></div>
        <div class="preview-summary"><span>数据预览（前 {{ previewRows.length }} 行）</span><small>标题和阅读量为必需字段，其他互动字段允许为空。</small></div>
        <div class="preview-table-wrap"><table><thead><tr><th v-for="header in sourceHeaders" :key="header">{{ header }}<small>{{ mappingLabel(fieldMapping[header]) }}</small></th></tr></thead><tbody><tr v-for="(row,index) in previewRows" :key="index"><td v-for="header in sourceHeaders" :key="header">{{ row[header] }}</td></tr></tbody></table></div>
        <footer class="preview-actions"><button @click="cancelPreview">重新选择</button><button class="primary" :disabled="mappingWarnings.length>0||loading" @click="confirmAnalysis">{{loading?'AI 分析中…':'确认并开始分析'}}</button></footer>
      </section>
    </div>
    <section class="metrics"><article v-for="m in cards" :key="m.key"><span>{{m.label}}</span><i>{{m.icon}}</i><strong>{{m.value}}</strong><small>{{m.desc}}</small></article></section>
    <section class="charts"><div class="panel"><Head title="阅读量趋势图" :text="`展示本次文件中的 ${all.length} 篇内容`"/><div ref="chartRef" class="chart"/></div><div class="panel"><Head title="内容表现可视化" text="阅读量与互动率双维对比，可滑动查看更多"/><div ref="performanceChartRef" class="chart"/></div></section>
    <section id="ai-report" class="panel report"><Head title="AI 运营分析" text="Coze Workflow 返回的完整报告"/><pre v-if="data.output">{{data.output}}</pre><Empty v-else text="上传数据后，AI 运营分析将在这里展示。"/></section>
    <section class="panel"><Head title="高表现内容" :text="`优先展示 top_views · TOP ${top.length}`"/><div v-if="top.length" class="table"><div class="tr th"><span>排名</span><span>标题</span><span>阅读量</span><span>互动率</span></div><div v-for="(x,i) in top" :key="x.title+i" class="tr"><span>0{{i+1}}</span><b>{{x.title}}</b><span>{{num(x.views)}}</span><em>{{rate(x.rate)}}</em></div></div><Empty v-else text="暂无高表现内容数据。"/></section>
    <section class="panel"><Head title="内容表现矩阵" text="横轴为阅读量，纵轴为互动率；中线为当前样本的中位水平"/><div class="matrix"><label class="a">潜力内容<small>高互动 · 低流量</small></label><label class="b">爆款内容<small>高互动 · 高流量</small></label><label class="c">待优化<small>低互动 · 低流量</small></label><label class="d">流量内容<small>低互动 · 高流量</small></label><button v-for="(x,i) in points" :key="x.title+i" class="matrix-point" :title="`${x.title} / 阅读量 ${num(x.views)} / 互动率 ${rate(x.rate)}`" :style="{left:x.left+'%',bottom:x.bottom+'%'}"><span>{{i+1}}</span></button></div><div v-if="points.length" class="matrix-legend"><div v-for="(x,i) in points" :key="x.title+i"><b>{{i+1}}</b><span>{{x.title}}</span><small>{{num(x.views)}} 阅读 · {{rate(x.rate)}} 互动</small></div></div><Empty v-else text="暂无可用于矩阵分析的内容明细。"/></section>
    <section class="panel"><Head title="AI 下一轮选题推荐" text="从报告和高表现内容中提炼方向"/><div v-if="topics.length" class="topics"><article v-for="(x,i) in topics" :key="x"><b>0{{i+1}}</b><strong>{{x}}</strong><button @click="startRecommendedTopic(x)">开始创作 →</button></article></div><Empty v-else text="完成分析后自动生成推荐方向。"/></section>
  </main>
</template>
<script setup>
import {computed,defineComponent,h,nextTick,onActivated,onBeforeUnmount,onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import * as echarts from 'echarts'
import * as XLSX from 'xlsx'
import {useAnalysisStore} from '../stores/analysis'
import {useContentStore} from '../stores/content'
import {runAnalyticsWorkflow} from '../api/cozeAnalytics'
import {databaseApi} from '../api/database'
const Head=defineComponent({props:['title','text'],setup:p=>()=>h('header',{class:'head'},[h('h2',p.title),h('p',p.text)])})
const Empty=defineComponent({props:['text'],setup:p=>()=>h('div',{class:'empty'},p.text)})
const router=useRouter(),analysisStore=useAnalysisStore(),contentStore=useContentStore(),fileInput=ref(),chartRef=ref(),performanceChartRef=ref(),loading=ref(false),errorMessage=ref(''),uploadedRows=ref([]),showPreview=ref(false),sourceRows=ref([]),sourceHeaders=ref([]),fieldMapping=ref({}),pendingFile=ref(null)
const standardFields=[{key:'title',label:'文章标题（必需）'},{key:'views',label:'阅读量（必需）'},{key:'likes',label:'点赞量'},{key:'collects',label:'收藏量'},{key:'comments',label:'评论量'},{key:'shares',label:'分享量'},{key:'interaction_rate',label:'互动率'}]
const fieldAliases={title:['title','标题','文章标题','内容标题','作品名称','笔记标题','文章名称'],views:['views','view','阅读量','阅读','浏览量','曝光量','曝光次数','播放量'],likes:['likes','like','点赞','点赞量','喜欢数','获赞数'],collects:['collects','collect','收藏','收藏量','收藏数'],comments:['comments','comment','评论','评论量','评论数'],shares:['shares','share','分享','分享量','转发','转发量'],interaction_rate:['interaction_rate','interactionrate','互动率','平均互动率']}
const blank=()=>({articleCount:0,totalViews:0,totalLikes:0,totalCollects:0,totalComments:0,totalShares:0,interactionRate:0,output:'',topViews:[],topInteraction:[]})
const data=ref(blank());let chart,performanceChart
const n=v=>{const text=String(v??'').replaceAll(',','').trim(),m=text.match(/-?[\d.]+/);if(!m)return 0;const value=Number(m[0])||0;if(/[万wW]/.test(text))return value*10000;if(/[千]/.test(text))return value*1000;if(/[kK]/.test(text))return value*1000;return value}
const num=v=>n(v).toLocaleString('zh-CN'),rate=v=>`${n(v)}%`
const parse=v=>{if(typeof v!=='string')return v;try{return JSON.parse(v.replace(/^\`\`\`(?:json)?|\`\`\`$/g,'').trim())}catch{return v}}
function list(v){v=parse(v);if(Array.isArray(v))return v.map((x,i)=>typeof x==='string'?{title:x,views:0,rate:0}:{title:x.title||x.name||`内容 ${i+1}`,views:n(x.views||x.view_count),rate:n(x.interaction_rate||x.rate)});return String(v||'').split(/\r?\n/).map(s=>{const title=s.replace(/^[-*\d.、\s]+/,'').split('|')[0],views=s.match(/阅读量?[:：]?\s*([\d,.]+)/)?.[1],r=s.match(/互动率[:：]?\s*([\d.]+)/)?.[1];return{title,views:n(views),rate:n(r)}}).filter(x=>x.title)}
function normalize(raw){let s=parse(raw);if(!s||typeof s!=='object')s={output:String(raw||'')};const o=parse(s.output),inside=o&&typeof o==='object'?o:{};const x={...inside,...s};return{articleCount:n(x.article_count),totalViews:n(x.total_views),totalLikes:n(x.total_likes),totalCollects:n(x.total_collects),totalComments:n(x.total_comments),totalShares:n(x.total_shares),interactionRate:n(x.interaction_rate),output:typeof s.output==='string'&&typeof o==='string'?s.output:String(x.report||inside.output||''),topViews:list(x.top_views),topInteraction:list(x.top_interaction)}}
const top=computed(()=>data.value.topViews),all=computed(()=>{const m=new Map();[...uploadedRows.value,...data.value.topViews,...data.value.topInteraction].forEach(x=>m.set(x.title,{...(m.get(x.title)||{}),...x}));return[...m.values()]})
const fileDesc=computed(()=>analysisStore.fileInfo?.name?[analysisStore.fileInfo.size,analysisStore.fileInfo.uploadTime].filter(Boolean).join(' · '):'支持 XLSX、CSV、TXT；内容将转换为字符串传入 Coze Workflow')
const previewRows=computed(()=>sourceRows.value.slice(0,5))
const mappingWarnings=computed(()=>{const targets=Object.values(fieldMapping.value).filter(Boolean),warnings=[];if(!targets.includes('title'))warnings.push('请选择一个字段作为文章标题');if(!targets.includes('views'))warnings.push('请选择一个字段作为阅读量');const duplicate=[...new Set(targets.filter((x,i)=>targets.indexOf(x)!==i))];if(duplicate.length)warnings.push(`同一系统字段不能重复映射：${duplicate.map(mappingLabel).join('、')}`);return warnings})
const cards=computed(()=>[['articleCount','文章数量','◈','当前分析周期'],['totalViews','总阅读量','◉','累计内容曝光'],['totalLikes','点赞','♥','内容认同反馈'],['totalCollects','收藏','◇','长期内容价值'],['totalComments','评论','≡','用户讨论反馈'],['totalShares','分享','↗','内容传播表现'],['interactionRate','互动率','%','整体互动表现']].map(([key,label,icon,desc])=>({key,label,icon,desc,value:key==='interactionRate'?rate(data.value[key]):num(data.value[key])})))
const points=computed(()=>{const a=all.value.filter(x=>x.views||x.rate).sort((x,y)=>y.views-x.views).slice(0,12);if(!a.length)return[];const views=a.map(x=>x.views),rates=a.map(x=>x.rate),minV=Math.min(...views),maxV=Math.max(...views),minR=Math.min(...rates),maxR=Math.max(...rates);const position=(value,min,max)=>max===min?50:18+(value-min)/(max-min)*64;return a.map(x=>({...x,left:position(x.views,minV,maxV),bottom:position(x.rate,minR,maxR)}))})
const topics=computed(()=>{const section=data.value.output.match(/(?:下一轮|选题推荐|推荐方向)[^\n]*\n([\s\S]*?)(?=\n#{1,4}|$)/)?.[1];const a=String(section||'').split(/\r?\n/).map(x=>x.replace(/^\s*[-*\d.、]+\s*/,'').replaceAll('**','').trim()).filter(x=>x.length>3&&x.length<80).slice(0,3);return a.length?a:top.value.slice(0,3).map(x=>`围绕「${x.title}」延展系列内容`)})
function mappingLabel(key){return standardFields.find(field=>field.key===key)?.label||'未使用'}
function autoMap(headers){const used=new Set(),result={};headers.forEach(header=>{const normalized=String(header).trim().toLowerCase().replace(/[\s_-]/g,'');const matched=Object.entries(fieldAliases).find(([key,aliases])=>!used.has(key)&&aliases.some(alias=>alias.toLowerCase().replace(/[\s_-]/g,'')===normalized));result[header]=matched?.[0]||'';if(matched)used.add(matched[0])});return result}
async function parseUploadFile(file){const ext=file.name.split('.').pop()?.toLowerCase();if(!['xlsx','csv','txt'].includes(ext))throw Error('仅支持 .xlsx、.csv、.txt 文件');const workbook=ext==='xlsx'?XLSX.read(await file.arrayBuffer(),{type:'array'}):XLSX.read(await file.text(),{type:'string'});const sheet=workbook.Sheets[workbook.SheetNames[0]];if(!sheet)throw Error('文件中没有可读取的工作表');const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});if(!rows.length)throw Error('文件中没有可分析的数据行');return rows}
function normalizeMappedRows(){const reverse={};Object.entries(fieldMapping.value).forEach(([header,target])=>{if(target)reverse[target]=header});return sourceRows.value.map((row,index)=>{const title=String(row[reverse.title]??'').trim(),rawViews=row[reverse.views],views=n(rawViews),likes=n(row[reverse.likes]),collects=n(row[reverse.collects]),comments=n(row[reverse.comments]),shares=n(row[reverse.shares]),supplied=reverse.interaction_rate?row[reverse.interaction_rate]:'';return{row:index+2,title,views,likes,collects,comments,shares,interaction_rate:supplied!==''?n(supplied):(views?(likes+collects+comments+shares)/views*100:0),validViews:String(rawViews??'').trim()!==''&&Number.isFinite(views)}}).filter(row=>row.title||row.validViews)}
function cancelPreview(){showPreview.value=false;sourceRows.value=[];sourceHeaders.value=[];fieldMapping.value={};pendingFile.value=null}
async function handleFileUpload(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;errorMessage.value='';try{const rows=await parseUploadFile(file);sourceRows.value=rows;sourceHeaders.value=Object.keys(rows[0]);fieldMapping.value=autoMap(sourceHeaders.value);pendingFile.value=file;showPreview.value=true}catch(err){errorMessage.value=err?.message||'文件读取失败，请检查文件格式'}}
async function confirmAnalysis(){if(mappingWarnings.value.length)return;loading.value=true;errorMessage.value='';try{const rows=normalizeMappedRows(),invalid=rows.filter(row=>!row.title||!row.validViews);if(!rows.length)throw Error('没有识别到有效数据');if(invalid.length)throw Error(`第 ${invalid.slice(0,3).map(row=>row.row).join('、')} 行缺少标题或阅读量`);uploadedRows.value=rows.map(row=>({title:row.title,views:row.views,rate:row.interaction_rate}));const workflowRows=rows.map(row=>({'标题':row.title,'阅读量':row.views,'点赞数':row.likes,'收藏数':row.collects,'评论数':row.comments,'分享数':row.shares})),worksheet=XLSX.utils.json_to_sheet(workflowRows,{header:['标题','阅读量','点赞数','收藏数','评论数','分享数']}),content=XLSX.utils.sheet_to_csv(worksheet);const file=pendingFile.value,result=await runAnalyticsWorkflow(content);data.value=normalize(result);analysisStore.saveAnalysis(result,file);databaseApi.saveAnalysis({fileName:file?.name||'',result}).catch(error=>console.warn('MySQL 分析记录保存失败：',error?.message));showPreview.value=false;await nextTick();render()}catch(err){console.error('数据预检或 Workflow 分析失败：',err);errorMessage.value=err?.message||'分析失败，请稍后重试'}finally{loading.value=false}}
function render(){const items=all.value,zoom=items.length>10?[{type:'inside',start:0,end:Math.min(100,1000/items.length)},{type:'slider',height:16,bottom:5,start:0,end:Math.min(100,1000/items.length)}]:[];if(chartRef.value){chart||=(echarts.init(chartRef.value));chart.setOption({tooltip:{trigger:'axis'},grid:{left:55,right:20,bottom:items.length>10?72:55},dataZoom:zoom,xAxis:{type:'category',data:items.map(x=>x.title),axisLabel:{rotate:20,formatter:v=>v.length>8?`${v.slice(0,8)}…`:v}},yAxis:{type:'value'},series:[{name:'阅读量',type:'line',smooth:true,areaStyle:{},data:items.map(x=>x.views)}]},true)}if(performanceChartRef.value){performanceChart||=(echarts.init(performanceChartRef.value));performanceChart.setOption({tooltip:{trigger:'axis'},legend:{},grid:{left:55,right:55,bottom:items.length>10?72:55},dataZoom:zoom,xAxis:{type:'category',data:items.map(x=>x.title),axisLabel:{formatter:v=>v.length>6?`${v.slice(0,6)}…`:v}},yAxis:[{type:'value'},{type:'value',axisLabel:{formatter:'{value}%'}}],series:[{name:'阅读量',type:'bar',barMaxWidth:28,data:items.map(x=>x.views)},{name:'互动率',type:'line',smooth:true,yAxisIndex:1,data:items.map(x=>x.rate)}]},true)}}
const resize=()=>{chart?.resize();performanceChart?.resize()},scrollToReport=()=>document.querySelector('#ai-report')?.scrollIntoView({behavior:'smooth'})
function startRecommendedTopic(topic){if(!topic)return;contentStore.setSelectedTopic(topic);router.push({path:'/create',query:{topic}})}
onMounted(async()=>{if(analysisStore.analysisResult)data.value=normalize(analysisStore.analysisResult);await nextTick();render();addEventListener('resize',resize)})
onActivated(async()=>{await nextTick();render();resize()})
onBeforeUnmount(()=>{removeEventListener('resize',resize);chart?.dispose();performanceChart?.dispose()})
</script>
<style scoped>
